import{Fn,vec2,uv,Loop,vec4,premultiplyAlpha,unpremultiplyAlpha,max,int,textureSize,nodeObject,convertToTexture}from"three/tsl";export const boxBlur=Fn(([e,t={}])=>{e=convertToTexture(e);const n=nodeObject(t.size)||int(1),o=nodeObject(t.separation)||int(1),i=t.premultipliedAlpha||!1,r=t=>{const n=e.sample(t);return i?premultiplyAlpha(n):n},p=e.uvNode||uv(),l=vec4(0),a=max(o,1),u=int(0),d=vec2(1).div(textureSize(e));return Loop({start:n.negate(),end:n,name:"i",condition:"<="},({i:e})=>{Loop({start:n.negate(),end:n,name:"j",condition:"<="},({j:t})=>{const n=p.add(vec2(e,t).mul(d).mul(a));l.addAssign(r(n)),u.addAssign(1)})}),l.divAssign(u),i?unpremultiplyAlpha(l):l});